CREATE TABLE IF NOT EXISTS v31_reservation_events (id BIGSERIAL PRIMARY KEY,reservation_id BIGINT NOT NULL REFERENCES v31_reservation_requests(id) ON DELETE CASCADE,from_status TEXT,to_status TEXT NOT NULL,actor_type TEXT NOT NULL CHECK(actor_type IN ('traveler','professional','system')),note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_v31_reservation_events_reservation ON v31_reservation_events(reservation_id,created_at);